// Terminal shell execution — SSE streaming, sandboxed to project root
router.post('/terminal/run', authMiddleware, (req, res) => {
    const { command } = req.body;
    if (typeof command !== 'string' || !command.trim()) {
        return res.status(400).json({ error: 'command required' });
    }
    res.writeHead(200, {
        'Content-Type': 'text/event-stream',
        'Cache-Control': 'no-cache',
        'Connection': 'keep-alive',
    });
    const send = (obj: object) => res.write(`data: ${JSON.stringify(obj)}\n\n`);
    const child = spawn(command, [], { cwd: SystemConfig.ROOT, shell: true, env: process.env });
    child.stdout.on('data', (d: Buffer) => send({ type: 'stdout', data: d.toString() }));
    child.stderr.on('data', (d: Buffer) => send({ type: 'stderr', data: d.toString() }));
    child.on('error', (err: Error) => { send({ type: 'stderr', data: err.message }); res.end(); });
    child.on('close', (code: number | null) => { send({ type: 'exit', code }); res.end(); });
    req.on('close', () => child.kill());
});

